function t(key){
  const dict = I18N[lang] || I18N.ar;
  return (dict[key] !== undefined) ? dict[key] : key;
}

/* The SOS sheet must always display in English, regardless of the
   app-wide language toggle, so SOS-specific rendering uses this
   instead of t(). */
function tEn(key){
  return (I18N.en[key] !== undefined) ? I18N.en[key] : key;
}

function unitLabel(u){
  if(u === "كغ" || u === "kg") return "KG";
  if(u === "مل" || u === "ml") return "ML";
  if(u === "لتر" || u === "l") return "L";
  return "G";
}

function dayWord(n){
  return n === 1 ? t("day_word") : t("days_word");
}

function setLang(l){
  lang = (l === "en") ? "en" : "ar";
  try{ localStorage.setItem("puck_lang", lang); }catch(e){}
  document.documentElement.lang = lang;
  document.documentElement.dir = lang === "ar" ? "rtl" : "ltr";
  render();
  if(document.getElementById("adminOverlay")) renderAdminOverlay();
}

function uid(){ return Math.random().toString(36).slice(2,10) + Date.now().toString(36); }

