/* ---------------- DAILY INVENTORY: seed catalog products per branch ---------------- */
function ensureCatalogSeededForBranch(branchId){
  const existingSkus = new Set(state.products.filter(p=>p.branchId===branchId).map(p=>p.sku).filter(Boolean));
  let added = false;
  PRODUCT_CATALOG.forEach(g=>{
    g.items.forEach(it=>{
      if(existingSkus.has(it.sku)) return;
      const view = getCatalogItemView(it);
      state.products.push({
        id: uid(), branchId, sku: view.sku, nameEn: view.en, name: view.ar, catalogItemId: it.id,
        image: "", weightValue: view.weightValue||0, weightUnit: view.weightUnit||"g",
        startDay: 1, startMonth: 1, endDay: 31, endMonth: 12, alertDays: 14, hidden: false
      });
      existingSkus.add(it.sku);
      added = true;
    });
  });
  // backfill catalogItemId on products seeded before this field existed
  let backfilled = false;
  state.products.forEach(p=>{
    if(p.branchId===branchId && !p.catalogItemId && p.sku){
      const cid = catalogItemIdBySku(p.sku);
      if(cid){ p.catalogItemId = cid; backfilled = true; }
    }
  });
  return added || backfilled;
}
async function ensureCatalogSeededAllBranches(){
  let anyAdded = false;
  state.branches.forEach(b=>{ if(ensureCatalogSeededForBranch(b.id)) anyAdded = true; });
  if(anyAdded) await storageSet("puck:products", state.products);
}

/* =========================================================
   ترحيل الفروع القديمة المشتركة إلى فروع خاصة بكل موظف
   -----------------------------------------------------------
   قديمًا كانت كل الفروع (بما فيها الفروع الافتراضية وأي فرع
   يضيفه أي موظف) مشتركة بين كل الحسابات بلا استثناء: أي تعديل
   على صورة/منتج في فرع يظهر فورًا لكل الموظفين لأنهم جميعًا
   يقرأون نفس السجل بنفس المعرّف. هذه الدالة تُنفَّذ مرة واحدة
   فقط: لكل فرع لا يملك "ownerId" (فرع قديم مشترك)، تُنشأ نسخة
   مستقلة كاملة (فرع + منتجاته) لكل موظف حالي، ثم يُحذف الفرع
   المشترك القديم. من هذه اللحظة فصاعدًا، أي تعديل يقوم به موظف
   في فرعه الخاص لا يؤثر إطلاقًا على فروع بقية الموظفين.
========================================================= */
async function migrateLegacyBranchOwnership(){
  if(state.settings && state.settings.branchOwnershipMigrated) return;
  const employees = state.users.filter(u=>userRole(u)==="employee");
  const legacyBranches = state.branches.filter(b=> !b.ownerId);
  if(legacyBranches.length && employees.length){
    const clonedBranches = [];
    const clonedProducts = [];
    legacyBranches.forEach(b=>{
      employees.forEach(emp=>{
        const newBranchId = uid();
        clonedBranches.push(Object.assign({}, b, {
          id: newBranchId,
          ownerId: emp.id,
          createdByRole: "employee",
          createdByName: emp.username,
          assignedEmployeeIds: [],
        }));
        state.products.filter(p=>p.branchId===b.id).forEach(p=>{
          clonedProducts.push(Object.assign({}, p, { id: uid(), branchId: newBranchId }));
        });
      });
    });
    const legacyIds = new Set(legacyBranches.map(b=>b.id));
    state.branches = state.branches.filter(b=> !legacyIds.has(b.id)).concat(clonedBranches);
    state.products = state.products.filter(p=> !legacyIds.has(p.branchId)).concat(clonedProducts);
    await storageSet("puck:branches", state.branches);
    await storageSet("puck:products", state.products);
  }
  state.settings.branchOwnershipMigrated = true;
  await storageSet("puck:settings", state.settings);
}

