/* ---------------- BRANCH PRODUCTS ---------------- */
function renderBranchScreen(branchId){
  const branch = state.branches.find(b=>b.id===branchId);
  const products = state.products.filter(p=>p.branchId===branchId && (!p.hidden || canEdit()));
  const cols = branchColumns(branch);
  const expiredCount = state.products.filter(p=>p.branchId===branchId && !p.hidden && expiryStatus(p).status==="expired").length;

  const groupsMap = new Map();
  const otherItems = [];
  products.forEach(p=>{
    const g = dailyProductGroupOf(p);
    if(g){
      if(!groupsMap.has(g.id)) groupsMap.set(g.id, []);
      groupsMap.get(g.id).push(p);
    } else otherItems.push(p);
  });

  function groupBlockHtml(titleAr, titleEn, items){
    const expiredInGroup = items.filter(p=>!p.hidden && expiryStatus(p).status==="expired").length;
    const cards = items.map(dailyProductCardHtml).join("");
    return `
      <details class="product-group" ${expiredInGroup>0 ? 'open' : ''}>
        <summary>
          <div class="mg-title">
            <div class="ar">${escapeHtml(titleAr)}</div>
            <div class="en">${escapeHtml(titleEn)}</div>
          </div>
          <div class="mg-meta">
            <span class="mg-count ${expiredInGroup>0?'has-filled':''}">${items.length} ${t('product_word')}</span>
            <span class="mg-chevron">${ICON.chevron}</span>
          </div>
        </summary>
        <div class="mg-body"><div class="product-grid cols-${cols}">${cards}</div></div>
      </details>
    `;
  }

  let groupsHtml = "";
  allCatalogGroupsList().forEach(g=>{
    const items = groupsMap.get(g.id);
    if(items && items.length) groupsHtml += groupBlockHtml(g.titleAr, g.titleEn, items);
  });
  if(otherItems.length) groupsHtml += groupBlockHtml(t('monthly_other_group_title'), t('monthly_other_group_title_en'), otherItems);
  if(!groupsHtml) groupsHtml = `<div class="branch-empty">${t('no_products_branch')}</div>`;

  return `
    <div class="topbar">
      <button class="back-btn" id="backBtn">${ICON.back} ${t('back')}</button>
      <div style="display:flex; align-items:center; gap:8px;">
        ${langToggleHtml()}${bellButtonHtml()}
        ${viewOnlyBackButtonHtml()}<button class="gear-btn" id="gearBtn" title="${t('control_panel')}">${ICON.gear}</button>
      </div>
    </div>
    <div class="products-wrap">
      <div class="branch-title-row">
        <h2>${escapeHtml(branch ? branch.name : "")}</h2>
        ${branch ? renderBranchNoticesHtml(branch) : ''}
        ${(canEdit() && branch) ? `<button class="notices-edit-link" data-manage-notices-inline="${branch.id}">${ICON.edit} ${t('manage_notices')}</button>` : ''}
      </div>
      <div class="branch-layout-row">
        <div class="layout-choice-row small">
          <div class="layout-opt small ${cols===1?'active':''}" data-branch-cols="1">
            <div class="preview"><div class="bar" style="width:26px;"></div></div>
            <div class="lbl">${t('layout_one_col')}</div>
          </div>
          <div class="layout-opt small ${cols===2?'active':''}" data-branch-cols="2">
            <div class="preview"><div class="bar"></div><div class="bar"></div></div>
            <div class="lbl">${t('layout_two_col')}</div>
          </div>
        </div>
      </div>
      ${expiredCount>0 ? `<div class="expired-alert-bar" data-goto-expired="${branchId}">${ICON.warn} ${t('expired_products_label')} (${expiredCount})</div>` : ''}
      ${canEdit() ? `<button class="btn btn-ghost" id="addCatalogCategoryBtn" style="max-width:900px; width:calc(100% - 40px); margin:0 auto 14px; display:block;">${ICON.plus} ${t('add_category_btn')}</button>` : ''}
      <div class="product-groups">${groupsHtml}</div>
      ${(canEdit() && branch) ? `<div style="max-width:900px; margin:18px auto 0; padding:0 20px;"><button class="add-product-tile" data-quick-add-product="${branch.id}">${ICON.plus} ${t('add_new_product')}</button></div>` : ''}
    </div>
  `;
}

