/* ---------------- MONTHLY INVENTORY: per-branch list ---------------- */
function monthlyProductRowHtml(branchId, opts){
  const { rowId, seq, ar, en, sku, weightValue, weightUnit, legacyUnit, editable, kind } = opts;
  const entry = getMonthlyEntry(branchId, rowId);
  const filled = entryIsFilled(entry);
  const unitStr = unitBilingual(weightUnit, legacyUnit);
  const showEnFirst = (lang === "en" && en);
  const primaryText = showEnFirst ? en : ar;
  const primaryDir = showEnFirst ? "ltr" : "rtl";
  const secondaryText = showEnFirst ? ar : en;
  const secondaryDir = showEnFirst ? "rtl" : "ltr";
  return `
    <div class="monthly-row ${filled?'filled':''}">
      <div class="m-info">
        <div class="m-seq">${seq}</div>
        <div class="m-info-text">
          <div class="m-name-ar" dir="${primaryDir}">${escapeHtml(primaryText)}</div>
          ${secondaryText ? `<div class="m-name-en" dir="${secondaryDir}">${escapeHtml(secondaryText)}</div>` : ''}
          <div class="m-weight">
            ${weightValue ? `<span class="tag">${weightValue} ${unitStr}</span>` : ''}
            ${sku ? `<span class="tag">${t('sku_word')} ${escapeHtml(sku)}</span>` : ''}
          </div>
        </div>
        <div class="m-row-actions">
          ${editable ? `<button class="m-edit-btn" data-monthly-row-edit="${rowId}" data-row-kind="${kind}" title="${t('quick_edit_title')}">${ICON.edit}</button>` : ''}
          ${editable && (kind==='catalog' || kind==='custom') ? `<button class="m-dup-btn" data-monthly-duplicate="${rowId}" data-row-kind="${kind}" title="${t('duplicate_word')}">${ICON.plus}</button>` : ''}
          ${editable && (kind==='duplicate') ? `<button class="m-del-btn" data-monthly-remove-dup="${rowId}" title="${t('remove_duplicate_word')}">${ICON.trash}</button>` : ''}
        </div>
      </div>
      <div class="m-shelf-back-grid">
        <div class="m-loc-block">
          <div class="m-loc-title">${t('monthly_col_shelf')} <span class="en-tag">SHELF</span></div>
          <div class="m-select-row">
            <select class="qty-select" data-row="${rowId}" data-entry-field="shelfQty" ${editable?'':'disabled'}>${qtyCartonOptionsHtml(entry.shelfQty)}</select>
            <span class="carton-lbl">${t('carton_unit_word')}</span>
          </div>
          <div class="m-select-row">
            <select data-row="${rowId}" data-entry-field="shelfDay" ${editable?'':'disabled'}>${dayOptionsWithNoneHtml(entry.shelfDay)}</select>
            <select data-row="${rowId}" data-entry-field="shelfMonth" ${editable?'':'disabled'}>${monthOptionsWithNoneHtml(entry.shelfMonth)}</select>
            <select data-row="${rowId}" data-entry-field="shelfYear" ${editable?'':'disabled'}>${yearOptionsWithNoneHtml(entry.shelfYear)}</select>
          </div>
        </div>
        <div class="m-loc-block">
          <div class="m-loc-title">${t('monthly_col_back')} <span class="en-tag">BACK DOOR</span></div>
          <div class="m-select-row">
            <select class="qty-select" data-row="${rowId}" data-entry-field="backQty" ${editable?'':'disabled'}>${qtyCartonOptionsHtml(entry.backQty)}</select>
            <span class="carton-lbl">${t('carton_unit_word')}</span>
          </div>
          <div class="m-select-row">
            <select data-row="${rowId}" data-entry-field="backDay" ${editable?'':'disabled'}>${dayOptionsWithNoneHtml(entry.backDay)}</select>
            <select data-row="${rowId}" data-entry-field="backMonth" ${editable?'':'disabled'}>${monthOptionsWithNoneHtml(entry.backMonth)}</select>
            <select data-row="${rowId}" data-entry-field="backYear" ${editable?'':'disabled'}>${yearOptionsWithNoneHtml(entry.backYear)}</select>
          </div>
        </div>
      </div>
      <div class="m-notes-row">
        <div class="m-field">
          <span>${t('field_notes')}</span>
          <input type="text" data-row="${rowId}" data-entry-text="notes" value="${escapeHtml(entry.notes||'')}" ${editable?'':'disabled'}>
        </div>
        <div class="m-field">
          <span>${t('field_reason')}</span>
          <input type="text" data-row="${rowId}" data-entry-text="reason" value="${escapeHtml(entry.reason||'')}" ${editable?'':'disabled'}>
        </div>
      </div>
    </div>
  `;
}

function renderMonthlyBranchScreen(branchId){
  const branch = state.branches.find(b=>b.id===branchId);
  const meta = state.monthlyMeta[branchId] || { responsibleName: "", branchNameManual: "" };
  const editable = canEdit();
  let seq = 0;
  const nextSeq = ()=> (++seq);

  const groupsHtml = allCatalogGroupsList().map(g=>{
    const items = itemsForGroupId(g.id);
    if(!items.length) return "";
    let filledInGroup = 0, totalInGroup = 0, rows = "";
    items.forEach(it=>{
      totalInGroup++;
      if(entryIsFilled(getMonthlyEntry(branchId, it.id))) filledInGroup++;
      rows += monthlyProductRowHtml(branchId, {
        rowId: it.id, seq: nextSeq(), ar: it.ar, en: it.en, sku: it.sku,
        weightValue: it.weightValue, weightUnit: it.weightUnit, editable, kind: "catalog"
      });
      state.monthlyDuplicates.filter(d=>d.branchId===branchId && d.sourceKind==="catalog" && d.sourceItemId===it.id).forEach(d=>{
        totalInGroup++;
        if(entryIsFilled(getMonthlyEntry(branchId, d.id))) filledInGroup++;
        rows += monthlyProductRowHtml(branchId, {
          rowId: d.id, seq: nextSeq(), ar: d.ar, en: d.en, sku: d.sku,
          weightValue: d.weightValue, weightUnit: d.weightUnit, editable, kind: "duplicate"
        });
      });
    });
    return `
      <details class="monthly-group" ${filledInGroup>0 ? 'open':''}>
        <summary>
          <div class="mg-title">
            <div class="ar">${escapeHtml(g.titleAr)}</div>
            <div class="en">${escapeHtml(g.titleEn)}</div>
          </div>
          <div class="mg-meta">
            <span class="mg-count ${filledInGroup>0?'has-filled':''}">${filledInGroup}/${totalInGroup}</span>
            <span class="mg-chevron">${ICON.chevron}</span>
          </div>
        </summary>
        <div class="mg-body">${rows}</div>
      </details>
    `;
  }).join("");

  const customProducts = state.monthlyProducts.filter(p=>p.branchId===branchId);
  let customFilled = 0, customTotal = 0, customRowsHtml = "";
  customProducts.forEach(p=>{
    customTotal++;
    if(entryIsFilled(getMonthlyEntry(branchId, p.id))) customFilled++;
    customRowsHtml += monthlyProductRowHtml(branchId, {
      rowId: p.id, seq: nextSeq(), ar: p.name, en: p.nameEn||'', sku: p.sku,
      weightValue: p.weightValue, weightUnit: p.weightUnit, legacyUnit: true, editable, kind: "custom"
    });
    state.monthlyDuplicates.filter(d=>d.branchId===branchId && d.sourceKind==="custom" && d.sourceItemId===p.id).forEach(d=>{
      customTotal++;
      if(entryIsFilled(getMonthlyEntry(branchId, d.id))) customFilled++;
      customRowsHtml += monthlyProductRowHtml(branchId, {
        rowId: d.id, seq: nextSeq(), ar: d.ar, en: d.en, sku: d.sku,
        weightValue: d.weightValue, weightUnit: d.weightUnit, editable, kind: "duplicate"
      });
    });
  });

  const otherGroupHtml = `
    <details class="monthly-group" ${customProducts.length ? 'open':''}>
      <summary>
        <div class="mg-title">
          <div class="ar">${t('monthly_other_group_title')}</div>
          <div class="en">${t('monthly_other_group_title_en')}</div>
        </div>
        <div class="mg-meta">
          <span class="mg-count ${customFilled>0?'has-filled':''}">${customFilled}/${customTotal}</span>
          <span class="mg-chevron">${ICON.chevron}</span>
        </div>
      </summary>
      <div class="mg-body">
        ${customRowsHtml || `<div class="branch-empty">${t('monthly_empty')}</div>`}
        ${editable ? `<button class="add-product-tile" id="monthlyAddBtn" data-branch="${branchId}" style="margin-top:4px;">${ICON.plus} ${t('add_new_product')}</button>` : ''}
      </div>
    </details>
  `;

  return `
    <div class="topbar">
      <button class="back-btn" id="monthlyBackBtn">${ICON.back} ${t('back')}</button>
      <div style="display:flex; align-items:center; gap:8px;">
        ${langToggleHtml()}${bellButtonHtml()}
        ${viewOnlyBackButtonHtml()}<button class="gear-btn" id="gearBtn" title="${t('control_panel')}">${ICON.gear}</button>
      </div>
    </div>
    <div class="branch-title-row">
      <h2>${escapeHtml(branch ? branch.name : "")}</h2>
      ${branch ? renderBranchNoticesHtml(branch) : ''}
    </div>
    <div class="monthly-wrap">
      <div class="field" style="margin-bottom:14px;">
        <label>${t('responsible_name_label')}</label>
        <input type="text" id="responsibleNameInput" placeholder="${t('responsible_name_placeholder')}" value="${escapeHtml(meta.responsibleName||'')}">
      </div>
      <div class="field" style="margin-bottom:14px;">
        <label>${t('branch_name_manual_label')}</label>
        <input type="text" id="branchNameManualInput" placeholder="${escapeHtml(branch ? branch.name : '')}" value="${escapeHtml(meta.branchNameManual || (branch ? branch.name : ''))}">
      </div>
      <p class="monthly-catalog-hint">${t('monthly_catalog_hint')}</p>
      ${editable ? `<button class="btn btn-ghost" id="addCatalogCategoryBtn" style="width:100%; margin-bottom:14px;">${ICON.plus} ${t('add_category_btn')}</button>` : ''}
      <div class="monthly-groups">${groupsHtml}${otherGroupHtml}</div>
    </div>
    <div class="monthly-actions">
      <button class="btn-download" id="monthlyDownloadBtn" data-branch="${branchId}">${ICON.download} ${t('download_word')}</button>
    </div>
  `;
}

