function updateMonthlyGroupBadge(detailsEl){
  if(!detailsEl) return;
  const rows = detailsEl.querySelectorAll(".monthly-row");
  const total = rows.length;
  let filled = 0;
  rows.forEach(r=>{ if(r.classList.contains("filled")) filled++; });
  const badge = detailsEl.querySelector(".mg-count");
  if(badge){
    badge.textContent = `${filled}/${total}`;
    badge.classList.toggle("has-filled", filled > 0);
  }
}

function escapeHtml(str){
  return String(str==null?"":str).replace(/[&<>"']/g, m => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
}

