function catalogUnitLabel(u){
  if(u === "kg") return "KG";
  if(u === "ml") return "ML";
  if(u === "l") return "L";
  return "G";
}
function monthlyEntryKey(branchId, itemId){ return branchId + "::" + itemId; }
function defaultMonthlyEntry(){
  return { shelfQty:0, shelfDay:0, shelfMonth:0, shelfYear:0, backQty:0, backDay:0, backMonth:0, backYear:0, notes:"", reason:"" };
}
function getMonthlyEntry(branchId, itemId){
  const key = monthlyEntryKey(branchId, itemId);
  return Object.assign(defaultMonthlyEntry(), state.monthlyEntries[key] || {});
}
async function patchMonthlyEntry(branchId, itemId, patch){
  const key = monthlyEntryKey(branchId, itemId);
  const cur = Object.assign(defaultMonthlyEntry(), state.monthlyEntries[key] || {});
  state.monthlyEntries[key] = Object.assign(cur, patch);
  await storageSet("puck:monthlyEntries", state.monthlyEntries);
}
function entryIsFilled(entry){ return (entry.shelfQty||0) > 0 || (entry.backQty||0) > 0; }
function unitBilingual(weightUnit, legacy){
  if(legacy){
    return (weightUnit === "كغ") ? "KG" : "G";
  }
  if(weightUnit === "kg") return "KG";
  if(weightUnit === "ml") return "ML";
  if(weightUnit === "l") return "L";
  return "G";
}
function catalogItemDisplayName(item){ return lang === "en" ? item.en : item.ar; }

/* ---------------- GLOBAL CATALOG: flat lookup, groups, moves, overrides ---------------- */
let _catalogFlatCache = null;
function allCatalogItemsFlat(){
  if(_catalogFlatCache) return _catalogFlatCache;
  const flat = [];
  PRODUCT_CATALOG.forEach(g=> g.items.forEach(it=> flat.push(it)));
  _catalogFlatCache = flat;
  return flat;
}
function getCatalogItemById(itemId){
  return allCatalogItemsFlat().find(it=>it.id===itemId) || null;
}
function defaultGroupIdOfItem(itemId){
  for(const g of PRODUCT_CATALOG){ if(g.items.some(it=>it.id===itemId)) return g.id; }
  return null;
}
function catalogItemGroupId(itemId){
  return state.catalogGroupOverrides[itemId] || defaultGroupIdOfItem(itemId);
}
function allCatalogGroupsList(){
  const base = PRODUCT_CATALOG.map(g=>({ id:g.id, titleAr:g.titleAr, titleEn:g.titleEn }));
  return base.concat(state.customCatalogGroups || []);
}
function getCatalogItemView(item){
  const ov = state.catalogOverrides[item.id];
  return ov ? Object.assign({}, item, ov) : item;
}
function getCatalogItemGlobalView(item){ return getCatalogItemView(item); }
function itemsForGroupId(groupId){
  return allCatalogItemsFlat()
    .filter(it => catalogItemGroupId(it.id) === groupId)
    .map(getCatalogItemView);
}
function catalogItemIdBySku(sku){
  if(!sku) return null;
  const it = allCatalogItemsFlat().find(x=>x.sku===sku);
  return it ? it.id : null;
}
async function saveGlobalCatalogOverride(itemId, patch){
  const cur = state.catalogOverrides[itemId] || {};
  state.catalogOverrides[itemId] = Object.assign({}, cur, patch);
  await storageSet("puck:catalogOverrides", state.catalogOverrides);
  let productsChanged = false;
  state.products.forEach(p=>{
    if(p.catalogItemId === itemId){
      if(patch.ar !== undefined) p.name = patch.ar;
      if(patch.en !== undefined) p.nameEn = patch.en;
      if(patch.sku !== undefined) p.sku = patch.sku;
      if(patch.weightValue !== undefined) p.weightValue = patch.weightValue;
      if(patch.weightUnit !== undefined) p.weightUnit = patch.weightUnit;
      productsChanged = true;
    }
  });
  if(productsChanged) await storageSet("puck:products", state.products);
}
async function saveGlobalCatalogGroupMove(itemId, newGroupId){
  state.catalogGroupOverrides[itemId] = newGroupId;
  await storageSet("puck:catalogGroupOverrides", state.catalogGroupOverrides);
}
async function addCustomCatalogGroup(titleAr, titleEn){
  const g = { id: "custom-" + uid(), titleAr: titleAr, titleEn: titleEn || titleAr };
  state.customCatalogGroups.push(g);
  await storageSet("puck:customCatalogGroups", state.customCatalogGroups);
  return g;
}
function branchCatalogFilledCount(branchId){
  let n = 0;
  PRODUCT_CATALOG.forEach(g=> g.items.forEach(it=>{
    if(entryIsFilled(getMonthlyEntry(branchId, it.id))) n++;
  }));
  state.monthlyDuplicates.filter(d=>d.branchId===branchId).forEach(d=>{
    if(entryIsFilled(getMonthlyEntry(branchId, d.id))) n++;
  });
  return n;
}
function branchCustomFilledCount(branchId){
  return state.monthlyProducts.filter(p=>p.branchId===branchId && entryIsFilled(getMonthlyEntry(branchId, p.id))).length;
}

