let loginRole = "employee";

function renderLoginScreen(){
  return `
    <div class="hero">
      <div class="logo-wrap"><img class="logo-main" src="${LOGO_SRC}" alt="Arla"><img class="logo-brands" src="${BRANDS_SRC}" alt="Arla Brands"></div>
      <div class="hero-eyebrow">${t('hero_eyebrow')}</div>
    </div>
    <div class="login-page-wrap">
      <h3 style="text-align:center;">${t('login_title')}</h3>
      <p class="hint" style="text-align:center;">${t('login_hint')}</p>
      <div class="role-choice-row">
        <button data-role="employee" class="${loginRole==='employee'?'active':''}" type="button">${t('role_employee')}</button>
        <button data-role="manager" class="${loginRole==='manager'?'active':''}" type="button">${t('role_manager')}</button>
      </div>
      <div id="loginError"></div>
      <div class="field"><label>${t('username_label')}</label><input id="loginUser" type="text" autocomplete="off"></div>
      <div class="field"><label>${t('password_label')}</label><input id="loginPass" type="password"></div>
      <button class="btn btn-primary" id="loginSubmit" style="width:100%;">${t('login_submit')}</button>
      <div style="text-align:center; margin-top:16px;">${langToggleHtml()}</div>
    </div>
  `;
}

function attachLoginScreenEvents(){
  document.querySelectorAll("[data-role]").forEach(btn=>{
    btn.onclick = ()=>{ loginRole = btn.getAttribute("data-role"); render(); };
  });
  document.querySelectorAll("#langToggle [data-lang]").forEach(btn=>{
    btn.onclick = ()=> setLang(btn.getAttribute("data-lang"));
  });
  const submit = ()=>{
    const u = document.getElementById("loginUser").value.trim();
    const p = document.getElementById("loginPass").value;
    const user = state.users.find(x=>x.username === u && x.password === p);
    const errBox = document.getElementById("loginError");
    if(!user){
      errBox.innerHTML = `<div class="error-msg">${t('login_error')}</div>`;
      return;
    }
    const role = userRole(user);
    if(loginRole === "employee" && role !== "employee"){
      errBox.innerHTML = `<div class="error-msg">${t('login_wrong_role_employee')}</div>`;
      return;
    }
    if(loginRole === "manager" && role === "employee"){
      errBox.innerHTML = `<div class="error-msg">${t('login_wrong_role_manager')}</div>`;
      return;
    }
    if(user.mustChange){ openForceChangeModal(user); return; }
    session.user = user;
    session.viewOnly = false;
    navigate({ screen:"landing", branchId:null });
    afterLoginCheck(user);
  };
  const submitBtn = document.getElementById("loginSubmit");
  if(submitBtn) submitBtn.onclick = submit;
  ["loginUser","loginPass"].forEach(id=>{
    const el = document.getElementById(id);
    if(el) el.onkeydown = (e)=>{ if(e.key === "Enter") submit(); };
  });
}

function afterLoginCheck(user){
  if(userRole(user) !== "employee") return;
  const hasUnread = state.messages.some(m=>m.toUserId===user.id && !m.read);
  if(hasUnread) openEmployeeNotificationsModal();
}

function openForceChangeModal(user){
  const wrap = document.createElement("div");
  wrap.className = "overlay";
  wrap.innerHTML = `
    <div class="modal">
      <h3>${t('fc_title')}</h3>
      <p class="hint">${t('fc_hint')}</p>
      <div id="fcError"></div>
      <div class="field"><label>${t('new_password_label')}</label><input id="newPass1" type="password"></div>
      <div class="field"><label>${t('confirm_password_label')}</label><input id="newPass2" type="password"></div>
      <button class="btn btn-primary" id="fcSubmit">${t('fc_submit')}</button>
    </div>
  `;
  document.body.appendChild(wrap);
  document.getElementById("fcSubmit").onclick = async ()=>{
    const p1 = document.getElementById("newPass1").value;
    const p2 = document.getElementById("newPass2").value;
    const errBox = document.getElementById("fcError");
    if(!p1 || p1.length < 4){ errBox.innerHTML = `<div class="error-msg">${t('fc_err_short')}</div>`; return; }
    if(p1 !== p2){ errBox.innerHTML = `<div class="error-msg">${t('fc_err_mismatch')}</div>`; return; }
    user.password = p1;
    user.mustChange = false;
    await storageSet("puck:users", state.users);
    wrap.remove();
    session.user = user;
    session.viewOnly = false;
    toast(t('toast_pass_updated'));
    navigate({ screen:"landing", branchId:null });
    afterLoginCheck(user);
  };
}

