function messageBodyHtml(m){
  let html = "";
  if(m.textAr && m.textEn){
    html += `<div class="msg-block"><div class="msg-lang-lbl">العربية</div><div class="msg-text">${escapeHtml(m.textAr)}</div></div>`;
    html += `<div class="msg-block"><div class="msg-lang-lbl">English</div><div class="msg-text">${escapeHtml(m.textEn)}</div></div>`;
  }else if(m.textAr){
    html += `<div class="msg-block"><div class="msg-lang-lbl">${t('original_text_label')} (عربي)</div><div class="msg-text">${escapeHtml(m.textAr)}</div></div>`;
  }else if(m.textEn){
    html += `<div class="msg-block"><div class="msg-lang-lbl">${t('original_text_label')} (English)</div><div class="msg-text">${escapeHtml(m.textEn)}</div></div>`;
  }
  return html;
}

function openEmployeeNotificationsModal(){
  if(!session.user) return;
  const myMessages = state.messages.filter(m=>m.toUserId===session.user.id).sort((a,b)=> b.createdAt - a.createdAt);
  const wrap = document.createElement("div");
  wrap.className = "overlay";

  function draw(){
    const listHtml = myMessages.length ? myMessages.map(m=>`
      <div class="notice-card">
        <div class="notice-card-meta">${escapeHtml(m.fromUsername)} — ${new Date(m.createdAt).toLocaleString(lang==='ar'?'ar-SA':'en-US')}</div>
        ${messageBodyHtml(m)}
        <label class="hide-toggle-row" style="margin-top:10px;">
          <input type="checkbox" data-mark-read="${m.id}" ${m.read?'checked':''} ${m.read?'disabled':''}>
          <span>${t('mark_as_read_label')}</span>
        </label>
      </div>
    `).join("") : `<p class="hint">${t('no_messages_yet')}</p>`;

    wrap.innerHTML = `
      <div class="modal wide">
        <button class="close-x" id="closeEmpMsg">&times;</button>
        <h3>${ICON.bell} ${t('message_from_manager_title')}</h3>
        <div id="empMsgList">${listHtml}</div>
        <button class="btn btn-ghost" id="closeEmpMsgBtn" style="width:100%; margin-top:10px;">${t('close_word')}</button>
      </div>
    `;
    document.getElementById("closeEmpMsg").onclick = ()=> wrap.remove();
    document.getElementById("closeEmpMsgBtn").onclick = ()=> wrap.remove();
    wrap.onclick = (e)=>{ if(e.target===wrap) wrap.remove(); };
    wrap.querySelectorAll("[data-mark-read]").forEach(cb=>{
      cb.onchange = async ()=>{
        const id = cb.getAttribute("data-mark-read");
        const m = state.messages.find(x=>x.id===id);
        if(!m) return;
        m.read = true;
        m.readAt = Date.now();
        await storageSet("puck:messages", state.messages);
        draw();
        render();
      };
    });
  }

  document.body.appendChild(wrap);
  draw();
}

