async function downloadSosExcel(branchId){
  if(typeof ExcelJS === "undefined"){ toast(tEn('sos_excel_error')); return; }
  toast(tEn('sos_excel_generating'));
  try{
    const data = sosNormalizeData(state.sos && Array.isArray(state.sos.categories) ? state.sos : defaultSosData());
    const categories = data.categories || [];
    const allBranches = data.branches || [];
    const branches = branchId ? allBranches.filter(b=>b.id===branchId) : allBranches;

    const NAVY_DEEP = "FF0E4526", ORANGE = "FFF6A623", SKY_LIGHT = "FFCFEFE6",
          YELLOW = "FFFFF6D6", GREEN = "FF92D050", BORDER_CLR = "FF8CA79A", WHITE = "FFFFFFFF";
    const thinBorder = { top:{style:"thin",color:{argb:BORDER_CLR}}, left:{style:"thin",color:{argb:BORDER_CLR}}, bottom:{style:"thin",color:{argb:BORDER_CLR}}, right:{style:"thin",color:{argb:BORDER_CLR}} };

    const wb = new ExcelJS.Workbook();
    const ws = wb.addWorksheet(tEn('tab_sos'), { views:[{ rightToLeft:false }] });

    const totalColCount = 3 + categories.reduce((n,c)=> n + Math.max(c.columns.length,1), 0);
    const hasNote = !!(data.printNote && data.printNote.trim());
    let headRow1, headRow2;
    if(hasNote){
      ws.mergeCells(1,1,1,totalColCount);
      const titleCell = ws.getCell(1,1);
      titleCell.value = data.printNote.trim();
      titleCell.font = { bold:true, size:13, color:{argb:NAVY_DEEP} };
      titleCell.alignment = { horizontal:"center", vertical:"middle" };
      ws.getRow(1).height = 20;
      headRow1 = 2; headRow2 = 3;
    } else {
      headRow1 = 1; headRow2 = 2;
    }

    const fSize = sosNameFontSize();

    // header row 1: id columns + category groups
    ["sos_col_merch","sos_col_sap","sos_col_customer"].forEach((k,i)=>{
      ws.mergeCells(headRow1, i+1, headRow2, i+1);
      const c = ws.getCell(headRow1, i+1);
      c.value = tEn(k);
      c.font = { bold:true, size: fSize, color:{argb:WHITE} };
      c.fill = { type:"pattern", pattern:"solid", fgColor:{argb:NAVY_DEEP} };
      c.alignment = { horizontal:"center", vertical:"middle", wrapText:true };
      c.border = thinBorder;
      const c2 = ws.getCell(headRow2, i+1);
      c2.fill = { type:"pattern", pattern:"solid", fgColor:{argb:NAVY_DEEP} };
      c2.border = thinBorder;
    });

    let colCursor = 4;
    const colMeta = []; // {col:excelColIndex, isPct}
    categories.forEach(cat=>{
      const span = Math.max(cat.columns.length,1);
      ws.mergeCells(headRow1, colCursor, headRow1, colCursor+span-1);
      const gc = ws.getCell(headRow1, colCursor);
      gc.value = cat.name;
      gc.font = { bold:true, size: fSize, color:{argb:NAVY_DEEP} };
      gc.fill = { type:"pattern", pattern:"solid", fgColor:{argb:ORANGE} };
      gc.alignment = { horizontal:"center", vertical:"middle", wrapText:true };
      for(let i=0;i<span;i++){
        const cell = ws.getCell(headRow1, colCursor+i);
        cell.border = thinBorder;
        const sub = ws.getCell(headRow2, colCursor+i);
        sub.value = cat.columns[i] ? cat.columns[i].label : "";
        sub.font = { bold:true, size: fSize, color:{argb:NAVY_DEEP} };
        sub.fill = { type:"pattern", pattern:"solid", fgColor:{argb:SKY_LIGHT} };
        sub.alignment = { horizontal:"center", vertical:"middle", wrapText:true };
        sub.border = thinBorder;
        colMeta.push({ col: colCursor+i, isPct: cat.columns[i] ? isSosPercentColumn(cat.columns[i]) : false, colId: cat.columns[i] ? cat.columns[i].id : null });
      }
      colCursor += span;
    });

    let rowCursor = headRow2 + 1;
    branches.forEach(b=>{
      const merchCell = ws.getCell(rowCursor,1); merchCell.value = b.merch||""; merchCell.font = { size: fSize }; merchCell.border = thinBorder; merchCell.alignment = { horizontal:"center", vertical:"middle" };
      const sapCell = ws.getCell(rowCursor,2); sapCell.value = b.sap||""; sapCell.font = { size: fSize }; sapCell.border = thinBorder; sapCell.alignment = { horizontal:"center", vertical:"middle" };
      const nameCell = ws.getCell(rowCursor,3);
      nameCell.value = b.name||"";
      nameCell.font = { bold:true, size: fSize };
      nameCell.fill = { type:"pattern", pattern:"solid", fgColor:{argb:YELLOW} };
      nameCell.alignment = { horizontal:"left", vertical:"middle", wrapText:true };
      nameCell.border = thinBorder;
      ws.getRow(rowCursor).height = Math.max(ws.getRow(rowCursor).height||15, fSize * 2);

      colMeta.forEach(cm=>{
        const val = cm.colId ? sosCellValue(b, cm.colId) : "";
        const cell = ws.getCell(rowCursor, cm.col);
        cell.value = (val==="") ? "" : Number(val);
          cell.numFmt = "[$-409]General"; // force Western digits regardless of Excel/Windows locale
        cell.font = { size: fSize };
        cell.alignment = { horizontal:"center", vertical:"middle" };
        cell.border = thinBorder;
        if(cm.isPct && val!==""){
          cell.fill = { type:"pattern", pattern:"solid", fgColor:{argb:GREEN} };
          cell.font = { bold:true, size: fSize };
        }
      });
      rowCursor++;
    });

    // column widths
    ws.getColumn(1).width = 12;
    ws.getColumn(2).width = 12;
    ws.getColumn(3).width = 28;
    for(let i=4;i<=totalColCount;i++) ws.getColumn(i).width = 10;

    const buffer = await wb.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    const fileSuffix = branchId && branches[0] ? `-${(branches[0].name||"").replace(/[^\u0600-\u06FFa-zA-Z0-9]+/g,"_")}` : "-all";
    a.href = url;
    a.download = `SOS-Report${fileSuffix}.xlsx`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(()=> URL.revokeObjectURL(url), 3000);
  }catch(err){
    console.error(err);
    toast(tEn('sos_excel_error'));
  }
}

/* ---------- BRANCH ICON MODAL ---------- */
const EMOJI_CHOICES = ["🏬","🛒","🏪","🏢","🧀","🥛","🍞","🥩","🍫","🥫","🍎","🧊","📍","⭐","🔥","🎯","🐼","🌿","💎","🛍"];
const COLOR_CHOICES = ["#2FA88F","#1B6B3D","#F6A623","#6FBE44","#D64545","#8E5CE0","#E05C9C","#2FB6A8"];

function openBranchIconModal(branchId){
  const branch = state.branches.find(b=>b.id===branchId);
  if(!branch) return;
  let cur = Object.assign({type:"daisy", value:""}, branchIcon(branch));
  let pendingImage = null;

  const wrap = document.createElement("div");
  wrap.className = "overlay";

  function subSectionHtml(){
    if(cur.type === "image"){
      return `
        <div class="field" style="text-align:center;">
          <div class="thumb-upload" style="margin:0 auto;">
            <img id="biImgPreview" src="${cur.value||''}" alt="">
            <input type="file" accept="image/*" id="biImageInput">
            <div class="up-hint">${ICON.upload} ${t('upload_image_word')}</div>
          </div>
        </div>`;
    }
    if(cur.type === "emoji"){
      return `
        <p class="hint" style="margin-bottom:0;">${t('choose_emoji_word')}</p>
        <div class="emoji-grid" id="biEmojiGrid">
          ${EMOJI_CHOICES.map(e=>`<button data-emoji="${e}" class="${cur.value===e?'active':''}" type="button">${e}</button>`).join("")}
        </div>`;
    }
    if(cur.type === "color"){
      return `
        <p class="hint" style="margin-bottom:0;">${t('choose_color_word')}</p>
        <div class="color-swatch-row" id="biColorRow">
          ${COLOR_CHOICES.map(c=>`<button data-color="${c}" class="${cur.value===c?'active':''}" type="button" style="background:${c};"></button>`).join("")}
          <input type="color" id="biCustomColor" value="${cur.value && cur.value.startsWith('#') ? cur.value : '#2FA88F'}">
        </div>`;
    }
    return `<p class="hint" style="margin-bottom:0;">${ICON.daisy}</p>`;
  }

  function draw(){
    wrap.innerHTML = `
      <div class="modal">
        <button class="close-x" id="closeIcon">&times;</button>
        <h3>${t('icon_modal_title')}</h3>
        <div class="icon-choice-row">
          <button data-itype="daisy" class="${cur.type==='daisy'?'active':''}" type="button">${t('icon_type_default')}</button>
          <button data-itype="image" class="${cur.type==='image'?'active':''}" type="button">${t('icon_type_image')}</button>
          <button data-itype="emoji" class="${cur.type==='emoji'?'active':''}" type="button">${t('icon_type_emoji')}</button>
          <button data-itype="color" class="${cur.type==='color'?'active':''}" type="button">${t('icon_type_color')}</button>
        </div>
        <div id="biSubSection">${subSectionHtml()}</div>
        <button class="btn btn-primary" id="biSaveBtn" style="margin-top:16px;">${t('save_word')}</button>
      </div>
    `;
    wire();
  }

  function wire(){
    document.getElementById("closeIcon").onclick = ()=> wrap.remove();
    wrap.onclick = (e)=>{ if(e.target===wrap) wrap.remove(); };
    wrap.querySelectorAll("[data-itype]").forEach(btn=>{
      btn.onclick = ()=>{ cur.type = btn.getAttribute("data-itype"); pendingImage = null; draw(); };
    });
    const imgInput = document.getElementById("biImageInput");
    if(imgInput) imgInput.onchange = (e)=>{
      const file = e.target.files[0];
      if(!file) return;
      compressImageToDataUrl(file, 300).then(dataUrl=>{
        pendingImage = dataUrl;
        document.getElementById("biImgPreview").src = dataUrl;
      });
    };
    const emojiGrid = document.getElementById("biEmojiGrid");
    if(emojiGrid) emojiGrid.querySelectorAll("[data-emoji]").forEach(btn=>{
      btn.onclick = ()=>{ cur.value = btn.getAttribute("data-emoji"); draw(); };
    });
    const colorRow = document.getElementById("biColorRow");
    if(colorRow){
      colorRow.querySelectorAll("[data-color]").forEach(btn=>{
        btn.onclick = ()=>{ cur.value = btn.getAttribute("data-color"); draw(); };
      });
      const customColor = document.getElementById("biCustomColor");
      if(customColor) customColor.oninput = ()=>{ cur.value = customColor.value; };
    }
    document.getElementById("biSaveBtn").onclick = async ()=>{
      if(cur.type === "image" && pendingImage) cur.value = pendingImage;
      branch.icon = { type: cur.type, value: cur.value || "" };
      await storageSet("puck:branches", state.branches);
      wrap.remove();
      toast(t('toast_icon_updated'));
      renderAdminOverlay();
    };
  }

  document.body.appendChild(wrap);
  draw();
}

/* ---------- BRANCH NOTICES MODAL ---------- */
function openBranchNoticesModal(branchId){
  const branch = state.branches.find(b=>b.id===branchId);
  if(!branch) return;
  branch.notices = branchNotices(branch);

  const wrap = document.createElement("div");
  wrap.className = "overlay";

  function listHtml(){
    if(!branch.notices.length) return `<p class="hint">${t('no_notices_yet')}</p>`;
    return branch.notices.map(n=>`
      <div class="notice-row">
        <span class="swatch" style="background:${escapeHtml(n.color||'#5C8A73')};"></span>
        <span class="txt" style="color:${escapeHtml(n.color||'#5C8A73')}; font-size:${parseInt(n.fontSize,10)||12}px;">${escapeHtml(n.text)}</span>
        <button data-del-notice="${n.id}" type="button">${ICON.trash}</button>
      </div>
    `).join("");
  }

  function draw(){
    wrap.innerHTML = `
      <div class="modal wide">
        <button class="close-x" id="closeNotices">&times;</button>
        <h3>${t('notices_modal_title')}</h3>
        <p class="hint">${t('notices_modal_hint')}</p>
        <div id="noticesList">${listHtml()}</div>
        <div class="notice-form">
          <input type="text" id="niText" placeholder="${t('notice_text_placeholder')}">
          <input type="color" id="niColor" value="#5C8A73" title="${t('notice_color_label')}">
          <input type="number" id="niSize" value="12" min="9" max="28" title="${t('notice_size_label')}">
          <button class="btn btn-primary btn-small" id="niAddBtn">${ICON.plus} ${t('add_notice_btn')}</button>
        </div>
      </div>
    `;
    document.getElementById("closeNotices").onclick = ()=> wrap.remove();
    wrap.onclick = (e)=>{ if(e.target===wrap) wrap.remove(); };
    wrap.querySelectorAll("[data-del-notice]").forEach(btn=>{
      btn.onclick = async ()=>{
        const id = btn.getAttribute("data-del-notice");
        branch.notices = branch.notices.filter(n=>n.id!==id);
        await storageSet("puck:branches", state.branches);
        toast(t('toast_notice_deleted'));
        draw();
      };
    });
    document.getElementById("niAddBtn").onclick = async ()=>{
      const text = document.getElementById("niText").value.trim();
      if(!text){ toast(t('toast_enter_notice_text')); return; }
      const color = document.getElementById("niColor").value;
      const fontSize = parseInt(document.getElementById("niSize").value,10) || 12;
      branch.notices.push({ id: uid(), text, color, fontSize });
      await storageSet("puck:branches", state.branches);
      toast(t('toast_notice_added'));
      draw();
    };
  }

  document.body.appendChild(wrap);
  draw();
}

/* ---------- PRODUCTS TAB ---------- */
function adminProductRowHtml(p){
  const monthOptions = (selected) => curMonthsAbbr3().map((m,i)=>`<option value="${i+1}" ${selected===i+1?'selected':''}>${String(i+1).padStart(2,'0')} ${m}</option>`).join("");
  const dayOptions = (selected) => Array.from({length:31},(_,i)=>i+1).map(d=>`<option value="${d}" ${selected===d?'selected':''}>${d}</option>`).join("");
  return `
    <div class="admin-product-row" data-product-id="${p.id}">
      <div class="thumb-upload">
        <img src="${p.image||''}" alt="">
        <input type="file" accept="image/*" data-upload-image="${p.id}">
        <div class="up-hint">${ICON.upload} ${t('change_word')}</div>
      </div>
      <div class="row-fields">
        <div class="line1">
          <input type="text" value="${escapeHtml(p.name)}" data-field="name" data-id="${p.id}" placeholder="${t('product_name_placeholder')}">
          <input type="text" value="${escapeHtml(p.nameEn||'')}" data-field="nameEn" data-id="${p.id}" placeholder="English Name" style="direction:ltr;">
          <input type="text" value="${escapeHtml(p.sku||'')}" data-field="sku" data-id="${p.id}" placeholder="${t('sku_placeholder')}" style="max-width:120px;">
          <div class="weight-inputs">
            <input type="number" min="0" value="${p.weightValue}" data-field="weightValue" data-id="${p.id}">
            <select data-field="weightUnit" data-id="${p.id}">
              <option value="غ" ${p.weightUnit==='غ'?'selected':''}>${t('unit_g')}</option>
              <option value="كغ" ${p.weightUnit==='كغ'?'selected':''}>${t('unit_kg')}</option>
            </select>
          </div>
        </div>
        <div class="date-line">
          <input type="hidden" data-field="startDay" data-id="${p.id}" value="1">
          <input type="hidden" data-field="startMonth" data-id="${p.id}" value="1">
          <div class="grp"><span>${t('date_end')}</span>
            <select data-field="endDay" data-id="${p.id}">${dayOptions(p.endDay)}</select>
            <select data-field="endMonth" data-id="${p.id}">${monthOptions(p.endMonth)}</select>
            <span>${YEAR}</span>
          </div>
          <div class="grp"><span>${ICON.warn} ${t('alert_before')}</span>
            <input type="number" min="0" max="120" style="width:56px;" value="${p.alertDays||0}" data-field="alertDays" data-id="${p.id}">
            <span>${t('day_word')}</span>
          </div>
        </div>
        <div class="row-actions">
          <label class="hide-toggle-row" style="margin:0;">
            <input type="checkbox" data-field="hidden" data-id="${p.id}" ${p.hidden ? 'checked' : ''}>
            <span>${t('hide_product_label')}</span>
          </label>
          ${p.catalogItemId ? `<button class="btn btn-ghost btn-small" data-admin-move-product="${p.catalogItemId}">${ICON.move || '↔️'} ${t('move_product_btn')}</button>` : ''}
          <button class="btn btn-danger btn-small" data-del-product="${p.id}">${ICON.trash} ${t('delete_product')}</button>
        </div>
      </div>
    </div>
  `;
}
function renderProductsTab(){
  const myBranches = visibleBranchesForCurrentUser();
  if(!myBranches.length){
    return `<div class="panel-card"><h4>${t('products_title')}</h4><p class="hint">${t('products_need_branch')}</p></div>`;
  }
  if(!adminUI.selectedBranchForProducts || !myBranches.some(b=>b.id===adminUI.selectedBranchForProducts)) adminUI.selectedBranchForProducts = myBranches[0].id;
  const selectRow = myBranches.map(b=>`<button class="${adminUI.selectedBranchForProducts===b.id?'active':''}" data-select-branch="${b.id}">${escapeHtml(b.name)}</button>`).join("");
  const products = state.products.filter(p=>p.branchId===adminUI.selectedBranchForProducts);

  const groupsMap = new Map();
  const otherItems = [];
  products.forEach(p=>{
    const g = dailyProductGroupOf(p);
    if(g){
      if(!groupsMap.has(g.id)) groupsMap.set(g.id, []);
      groupsMap.get(g.id).push(p);
    } else otherItems.push(p);
  });

  function groupBlockHtml(titleAr, titleEn, items){
    const rows = items.map(adminProductRowHtml).join("");
    return `
      <details class="monthly-group">
        <summary>
          <div class="mg-title">
            <div class="ar">${escapeHtml(titleAr)}</div>
            <div class="en">${escapeHtml(titleEn)}</div>
          </div>
          <div class="mg-meta">
            <span class="mg-count">${items.length}</span>
            <span class="mg-chevron">${ICON.chevron}</span>
          </div>
        </summary>
        <div class="mg-body">${rows}</div>
      </details>
    `;
  }

  let groupsHtml = "";
  allCatalogGroupsList().forEach(g=>{
    const items = groupsMap.get(g.id);
    if(items && items.length) groupsHtml += groupBlockHtml(g.titleAr, g.titleEn, items);
  });
  if(otherItems.length) groupsHtml += groupBlockHtml(t('monthly_other_group_title'), t('monthly_other_group_title_en'), otherItems);
  if(!groupsHtml) groupsHtml = `<p class="hint">${t('no_products_yet')}</p>`;

  return `
    <div class="panel-card">
      <h4>${t('choose_branch')}</h4>
      <div class="branch-select-row">${selectRow}</div>
    </div>
    <div class="panel-card">
      <h4>${t('branch_products')}</h4>
      <div class="monthly-groups" style="margin-top:14px;">${groupsHtml}</div>
      <button class="add-product-tile" id="addProductBtn">${ICON.plus} ${t('add_new_product')}</button>
    </div>
  `;
}

function attachProductsTabEvents(){
  document.querySelectorAll("[data-select-branch]").forEach(b=>{
    b.onclick = ()=>{ adminUI.selectedBranchForProducts = b.getAttribute("data-select-branch"); renderAdminOverlay(); };
  });
  const addBtn = document.getElementById("addProductBtn");
  if(addBtn) addBtn.onclick = ()=> openAddProductChoiceModal();
  document.querySelectorAll("[data-admin-move-product]").forEach(btn=>{
    btn.onclick = ()=> openCatalogMoveModal(btn.getAttribute("data-admin-move-product"));
  });
  document.querySelectorAll("[data-field]").forEach(inp=>{
    inp.onchange = async ()=>{
      const id = inp.getAttribute("data-id");
      const field = inp.getAttribute("data-field");
      const p = state.products.find(x=>x.id===id);
      if(!p) return;
      let val = inp.type === "checkbox" ? inp.checked : inp.value;
      if(["weightValue","startDay","startMonth","endDay","endMonth","alertDays"].includes(field)) val = parseInt(val,10)||0;
      p[field] = val;
      await storageSet("puck:products", state.products);
      if(p.catalogItemId && ["name","nameEn","sku","weightValue","weightUnit"].includes(field)){
        const unitMap = { "غ":"g", "كغ":"kg" };
        await saveGlobalCatalogOverride(p.catalogItemId, {
          ar: p.name, en: p.nameEn, sku: p.sku,
          weightValue: p.weightValue, weightUnit: unitMap[p.weightUnit] || p.weightUnit
        });
      }
      toast(t('toast_change_saved'));
    };
  });
  document.querySelectorAll("[data-upload-image]").forEach(inp=>{
    inp.onchange = (e)=>{
      const id = inp.getAttribute("data-upload-image");
      const file = e.target.files[0];
      if(!file) return;
      compressImageToDataUrl(file, 640).then(async dataUrl=>{
        const p = state.products.find(x=>x.id===id);
        if(p){ p.image = dataUrl; await storageSet("puck:products", state.products); toast(t('toast_image_updated')); renderAdminOverlay(); }
      });
    };
  });
  document.querySelectorAll("[data-del-product]").forEach(b=>{
    b.onclick = async ()=>{
      const id = b.getAttribute("data-del-product");
      if(!confirm(t('confirm_delete_product'))) return;
      state.products = state.products.filter(x=>x.id!==id);
      await storageSet("puck:products", state.products);
      toast(t('toast_product_deleted'));
      renderAdminOverlay();
    };
  });
}

