function attachUsersTabEvents(){
  const genBtn = document.getElementById("genCodeBtn");
  if(genBtn) genBtn.onclick = ()=>{
    const code = Math.floor(100000 + Math.random()*900000).toString();
    document.getElementById("newUserCode").value = code;
  };
  const addBtn = document.getElementById("addUserBtn");
  if(addBtn) addBtn.onclick = async ()=>{
    const username = document.getElementById("newUsername").value.trim();
    const employeeNumber = document.getElementById("newEmployeeNumber").value.trim();
    const phone = document.getElementById("newUserPhone").value.trim();
    const code = document.getElementById("newUserCode").value.trim();
    const role = document.getElementById("newUserRole").value;
    if(!username || !code){ toast(t('toast_enter_user_code')); return; }
    if(state.users.some(u=>u.username===username)){ toast(t('toast_user_exists')); return; }
    state.users.push({ id: uid(), username, employeeNumber, phone, password: code, role, mustChange: true, isAdmin: false, isDefault: false });
    await storageSet("puck:users", state.users);
    toast(t('toast_user_added_share') + code);
    renderAdminOverlay();
  };
  document.querySelectorAll("[data-del-user]").forEach(b=>{
    b.onclick = async ()=>{
      const id = b.getAttribute("data-del-user");
      if(!confirm(t('confirm_delete_user'))) return;
      state.users = state.users.filter(x=>x.id!==id);
      await storageSet("puck:users", state.users);
      toast(t('toast_user_deleted'));
      renderAdminOverlay();
    };
  });
  document.querySelectorAll("[data-edit-user]").forEach(b=>{
    b.onclick = ()=> openEditUserModal(b.getAttribute("data-edit-user"));
  });
  const myAccountBtn = document.getElementById("openMyAccountBtn");
  if(myAccountBtn) myAccountBtn.onclick = ()=> openMyAccountModal();
}

/* ---------- EDIT USER (BIGBOSS: edit employee username / employee number) ---------- */
function openEditUserModal(id){
  const user = state.users.find(u=>u.id===id);
  if(!user) return;
  const wrap = document.createElement("div");
  wrap.className = "overlay";
  wrap.innerHTML = `
    <div class="modal">
      <button class="close-x" id="euClose">&times;</button>
      <h3>${ICON.edit} ${t('edit_user_title')}</h3>
      <div id="euError"></div>
      <div class="field"><label>${t('username_label')}</label><input id="euUsername" type="text" value="${escapeHtml(user.username)}"></div>
      <div class="field"><label>${t('employee_number_label')}</label><input id="euEmployeeNumber" type="text" value="${escapeHtml(user.employeeNumber||'')}"></div>
      <div class="field"><label>${t('phone_label')}</label><input id="euPhone" type="text" value="${escapeHtml(user.phone||'')}" placeholder="${t('phone_placeholder')}" style="direction:ltr;"></div>
      <button class="btn btn-primary" id="euSaveBtn">${t('save_word')}</button>
      <button class="btn btn-ghost" id="euCancelBtn" style="width:100%; margin-top:8px;">${t('cancel_word')}</button>
    </div>
  `;
  document.body.appendChild(wrap);
  document.getElementById("euClose").onclick = ()=> wrap.remove();
  document.getElementById("euCancelBtn").onclick = ()=> wrap.remove();
  wrap.onclick = (e)=>{ if(e.target===wrap) wrap.remove(); };

  document.getElementById("euSaveBtn").onclick = async ()=>{
    const errBox = document.getElementById("euError");
    const newUsername = document.getElementById("euUsername").value.trim();
    const newEmployeeNumber = document.getElementById("euEmployeeNumber").value.trim();

    if(!newUsername){ errBox.innerHTML = `<div class="error-msg">${t('toast_enter_username')}</div>`; return; }
    if(state.users.some(u=>u.id!==user.id && u.username===newUsername)){ errBox.innerHTML = `<div class="error-msg">${t('toast_user_exists')}</div>`; return; }

    user.username = newUsername;
    user.employeeNumber = newEmployeeNumber;
    user.phone = document.getElementById("euPhone").value.trim();
    await storageSet("puck:users", state.users);
    wrap.remove();
    toast(t('toast_account_updated'));
    renderAdminOverlay();
  };
}

/* ---------- MY ACCOUNT (change own username/password) ---------- */
function openMyAccountModal(){
  const user = state.users.find(u=>u.id===session.user.id);
  if(!user) return;
  const wrap = document.createElement("div");
  wrap.className = "overlay";
  wrap.innerHTML = `
    <div class="modal">
      <button class="close-x" id="closeMyAccount">&times;</button>
      <h3>${ICON.edit} ${t('my_account_title')}</h3>
      <div id="myAccountError"></div>
      <div class="field"><label>${t('current_password_label')}</label><input id="maCurrentPass" type="password"></div>
      <div class="field"><label>${t('username_label')}</label><input id="maUsername" type="text" value="${escapeHtml(user.username)}"></div>
      <div class="field"><label>${t('new_password_label')} (${t('optional_word')})</label><input id="maNewPass1" type="password"></div>
      <div class="field"><label>${t('confirm_password_label')}</label><input id="maNewPass2" type="password"></div>
      <button class="btn btn-primary" id="maSaveBtn">${t('save_word')}</button>
      <button class="btn btn-ghost" id="maCancelBtn" style="width:100%; margin-top:8px;">${t('cancel_word')}</button>
    </div>
  `;
  document.body.appendChild(wrap);
  document.getElementById("closeMyAccount").onclick = ()=> wrap.remove();
  document.getElementById("maCancelBtn").onclick = ()=> wrap.remove();
  wrap.onclick = (e)=>{ if(e.target===wrap) wrap.remove(); };

  document.getElementById("maSaveBtn").onclick = async ()=>{
    const errBox = document.getElementById("myAccountError");
    const curPass = document.getElementById("maCurrentPass").value;
    const newUsername = document.getElementById("maUsername").value.trim();
    const newPass1 = document.getElementById("maNewPass1").value;
    const newPass2 = document.getElementById("maNewPass2").value;

    if(curPass !== user.password){ errBox.innerHTML = `<div class="error-msg">${t('toast_current_password_wrong')}</div>`; return; }
    if(!newUsername){ errBox.innerHTML = `<div class="error-msg">${t('toast_enter_username')}</div>`; return; }
    if(state.users.some(u=>u.id!==user.id && u.username===newUsername)){ errBox.innerHTML = `<div class="error-msg">${t('toast_user_exists')}</div>`; return; }
    if(newPass1 || newPass2){
      if(newPass1.length < 4){ errBox.innerHTML = `<div class="error-msg">${t('fc_err_short')}</div>`; return; }
      if(newPass1 !== newPass2){ errBox.innerHTML = `<div class="error-msg">${t('fc_err_mismatch')}</div>`; return; }
      user.password = newPass1;
    }
    user.username = newUsername;
    await storageSet("puck:users", state.users);
    wrap.remove();
    toast(t('toast_account_updated'));
    renderAdminOverlay();
  };
}

/* ---------- APPEARANCE TAB ---------- */
function renderAppearanceTab(){
  const fontOpts = FONT_OPTIONS.concat((state.settings.customFonts||[]).map(f=>({value:`'${f.name}', sans-serif`, label: f.name + t('custom_suffix')})));
  const fontOptionsHtml = fontOpts.map(f=>`<option value="${f.value}" ${state.settings.fontFamily===f.value?'selected':''}>${f.label}</option>`).join("");
  const weightOptsHtml = weightOptions().map(w=>`<option value="${w.value}" ${state.settings.fontWeight==w.value?'selected':''}>${w.label}</option>`).join("");
  const customFontChips = (state.settings.customFonts||[]).map(f=>`
    <div class="chip">${escapeHtml(f.name)}<button data-del-font="${f.name}">${ICON.trash}</button></div>
  `).join("");

  return `
    <div class="panel-card">
      <h4>${t('font_type_title')}</h4>
      <div class="font-select-grid">
        <div class="field"><label>${t('font_family_label')}</label><select id="fontFamilySelect">${fontOptionsHtml}</select></div>
        <div class="field"><label>${t('font_weight_label')}</label><select id="fontWeightSelect">${weightOptsHtml}</select></div>
      </div>
      <div class="field">
        <label>${t('base_font_size_label')}<span id="fontSizeLabel">${state.settings.fontSize}px</span></label>
        <div class="range-row"><input type="range" id="fontSizeRange" min="13" max="24" value="${state.settings.fontSize}"></div>
      </div>
    </div>
    <div class="panel-card">
      <h4>${t('upload_custom_font_title')}</h4>
      <input type="file" id="customFontInput" accept=".ttf,.otf,.woff,.woff2">
      <div class="custom-font-list">${customFontChips}</div>
    </div>
  `;
}
function attachAppearanceTabEvents(){
  const famSel = document.getElementById("fontFamilySelect");
  famSel.onchange = async ()=>{ state.settings.fontFamily = famSel.value; applySettings(); await storageSet("puck:settings", state.settings); toast(t('toast_font_updated')); };

  const wSel = document.getElementById("fontWeightSelect");
  wSel.onchange = async ()=>{ state.settings.fontWeight = parseInt(wSel.value,10); applySettings(); await storageSet("puck:settings", state.settings); toast(t('toast_weight_updated')); };

  const sizeRange = document.getElementById("fontSizeRange");
  sizeRange.oninput = ()=>{ document.getElementById("fontSizeLabel").textContent = sizeRange.value + "px"; state.settings.fontSize = parseInt(sizeRange.value,10); applySettings(); };
  sizeRange.onchange = async ()=>{ await storageSet("puck:settings", state.settings); toast(t('toast_size_updated')); };

  const fontInput = document.getElementById("customFontInput");
  fontInput.onchange = (e)=>{
    const file = e.target.files[0];
    if(!file) return;
    const reader = new FileReader();
    reader.onload = async (ev)=>{
      const dataUrl = ev.target.result;
      const name = file.name.replace(/\.[^.]+$/, "").replace(/[^a-zA-Z0-9أ-ي_\-]/g,"_");
      state.settings.customFonts = state.settings.customFonts || [];
      state.settings.customFonts = state.settings.customFonts.filter(f=>f.name!==name);
      state.settings.customFonts.push({ name, dataUrl });
      registerFont(name, dataUrl);
      await storageSet("puck:settings", state.settings);
      toast(t('toast_font_uploaded') + name);
      renderAdminOverlay();
    };
    reader.readAsDataURL(file);
  };
  document.querySelectorAll("[data-del-font]").forEach(b=>{
    b.onclick = async ()=>{
      const name = b.getAttribute("data-del-font");
      state.settings.customFonts = (state.settings.customFonts||[]).filter(f=>f.name!==name);
      if(state.settings.fontFamily.includes(name)){ state.settings.fontFamily = "'Tajawal', sans-serif"; applySettings(); }
      await storageSet("puck:settings", state.settings);
      toast(t('toast_font_deleted'));
      renderAdminOverlay();
    };
  });
}

