/* ---------------- MANAGER: expiry alerts (from monthly inventory data) ---------------- */
function computeManagerExpiryAlerts(branchIds, alertDaysThreshold){
  const rows = [];
  const today = new Date(); today.setHours(0,0,0,0);
  function daysUntil(day, month, year){
    if(!day || !month || !year) return null;
    const d = new Date(year, month-1, day); d.setHours(0,0,0,0);
    return Math.round((d - today) / 86400000);
  }
  function pushIfNeeded(branchId, ar, en, sku, weightValue, weightUnit, legacy, qty, day, month, year, location){
    if(!qty || qty <= 0) return;
    const days = daysUntil(day, month, year);
    if(days === null) return;
    if(days <= alertDaysThreshold){
      const branch = state.branches.find(b=>b.id===branchId);
      rows.push({
        name: lang==="en" && en ? en : ar, sku: sku||"", weightValue: weightValue||0,
        weightUnit: unitBilingual(weightUnit, legacy), days, location,
        branchName: branch ? branch.name : ""
      });
    }
  }
  branchIds.forEach(branchId=>{
    allCatalogItemsFlat().forEach(it=>{
      const view = getCatalogItemView(it);
      const entry = getMonthlyEntry(branchId, it.id);
      pushIfNeeded(branchId, view.ar, view.en, view.sku, view.weightValue, view.weightUnit, false, entry.shelfQty, entry.shelfDay, entry.shelfMonth, entry.shelfYear, "shelf");
      pushIfNeeded(branchId, view.ar, view.en, view.sku, view.weightValue, view.weightUnit, false, entry.backQty, entry.backDay, entry.backMonth, entry.backYear, "back");
    });
    state.monthlyDuplicates.filter(d=>d.branchId===branchId).forEach(d=>{
      const entry = getMonthlyEntry(branchId, d.id);
      pushIfNeeded(branchId, d.ar, d.en, d.sku, d.weightValue, d.weightUnit, false, entry.shelfQty, entry.shelfDay, entry.shelfMonth, entry.shelfYear, "shelf");
      pushIfNeeded(branchId, d.ar, d.en, d.sku, d.weightValue, d.weightUnit, false, entry.backQty, entry.backDay, entry.backMonth, entry.backYear, "back");
    });
    state.monthlyProducts.filter(p=>p.branchId===branchId).forEach(p=>{
      const entry = getMonthlyEntry(branchId, p.id);
      pushIfNeeded(branchId, p.name, p.nameEn, p.sku, p.weightValue, p.weightUnit, true, entry.shelfQty, entry.shelfDay, entry.shelfMonth, entry.shelfYear, "shelf");
      pushIfNeeded(branchId, p.name, p.nameEn, p.sku, p.weightValue, p.weightUnit, true, entry.backQty, entry.backDay, entry.backMonth, entry.backYear, "back");
    });
  });
  rows.sort((a,b)=> a.days - b.days);
  return rows;
}
