function downloadMonthlyPdf(branchId){
  let printArea = document.getElementById("monthlyPrintArea");
  if(!printArea){
    printArea = document.createElement("div");
    printArea.id = "monthlyPrintArea";
    printArea.className = "print-only";
    document.body.appendChild(printArea);
  }
  const branch = state.branches.find(b=>b.id===branchId);
  const meta = state.monthlyMeta[branchId] || {};
  const now = new Date();
  const gregorianStr = now.toLocaleDateString("en-GB");
  let hijriStr = "";
  try{ hijriStr = now.toLocaleDateString("ar-SA-u-ca-islamic", { day:"numeric", month:"numeric", year:"numeric" }); }catch(e){ hijriStr = ""; }
  const branchNameFinal = (meta.branchNameManual && meta.branchNameManual.trim()) || (branch ? branch.name : "");
  const employeeName = session.user ? employeeLabel(session.user) : (meta.responsibleName || "");

  function fmtExpiry(day, month, year){
    if(!day || !month || !year) return '';
    return `${String(day).padStart(2,'0')}/${String(month).padStart(2,'0')}/${year}`;
  }
  function bilingualName(ar, en){
    if(en && en.trim()) return `${ar} / ${en}`;
    return ar;
  }

  let seq = 0;
  let rows = "";
  function rowHtml(ar, en, sku, weightValue, weightUnit, legacy, entry){
    seq++;
    return `
      <tr>
        <td>${seq}</td>
        <td>${escapeHtml(sku||'')}</td>
        <td style="text-align:${lang==='ar'?'right':'left'};">${escapeHtml(bilingualName(ar, en))}</td>
        <td>${weightValue||0} ${unitBilingual(weightUnit, legacy)}</td>
        <td>${entry.shelfQty||0}</td>
        <td>${fmtExpiry(entry.shelfDay, entry.shelfMonth, entry.shelfYear)}</td>
        <td>${entry.backQty||0}</td>
        <td>${fmtExpiry(entry.backDay, entry.backMonth, entry.backYear)}</td>
        <td>${escapeHtml(entry.notes||'')}</td>
        <td>${escapeHtml(entry.reason||'')}</td>
      </tr>
    `;
  }

  allCatalogGroupsList().forEach(g=>{
    const groupRows = [];
    itemsForGroupId(g.id).forEach(it=>{
      const entry = getMonthlyEntry(branchId, it.id);
      if(entryIsFilled(entry)){
        groupRows.push(rowHtml(it.ar, it.en, it.sku, it.weightValue, it.weightUnit, false, entry));
      }
      state.monthlyDuplicates.filter(d=>d.branchId===branchId && d.sourceKind==="catalog" && d.sourceItemId===it.id).forEach(d=>{
        const dEntry = getMonthlyEntry(branchId, d.id);
        if(entryIsFilled(dEntry)) groupRows.push(rowHtml(d.ar, d.en, d.sku, d.weightValue, d.weightUnit, false, dEntry));
      });
    });
    if(groupRows.length){
      rows += `<tr class="p-group-row"><td colspan="10">${escapeHtml(lang==='en' ? g.titleEn : g.titleAr)}</td></tr>`;
      rows += groupRows.join("");
    }
  });

  const customProducts = state.monthlyProducts.filter(p=>p.branchId===branchId);
  const customRows = [];
  customProducts.forEach(p=>{
    const entry = getMonthlyEntry(branchId, p.id);
    if(entryIsFilled(entry)) customRows.push(rowHtml(p.name, p.nameEn, p.sku, p.weightValue, p.weightUnit, true, entry));
    state.monthlyDuplicates.filter(d=>d.branchId===branchId && d.sourceKind==="custom" && d.sourceItemId===p.id).forEach(d=>{
      const dEntry = getMonthlyEntry(branchId, d.id);
      if(entryIsFilled(dEntry)) customRows.push(rowHtml(d.ar, d.en, d.sku, d.weightValue, d.weightUnit, false, dEntry));
    });
  });
  if(customRows.length){
    rows += `<tr class="p-group-row"><td colspan="10">${escapeHtml(t('monthly_other_group_title'))}</td></tr>`;
    rows += customRows.join("");
  }

  if(!rows){ rows = `<tr><td colspan="10">${t('monthly_empty')}</td></tr>`; }

  printArea.innerHTML = `
    <h2>${t('monthly_print_title')}</h2>
    <div class="p-date">${t('branch_label')}: ${escapeHtml(branchNameFinal)}</div>
    <div class="p-date">${t('employee_label')}: ${escapeHtml(employeeName)}</div>
    <div class="p-date">${t('responsible_name_label')}: ${escapeHtml(meta.responsibleName || "")}</div>
    <div class="p-date">${t('gregorian_label')}: ${gregorianStr}${hijriStr ? `  |  ${t('hijri_label')}: ${hijriStr}` : ''}</div>
    <table>
      <thead><tr>
        <th>#</th><th>${t('sku_label')}</th><th>${t('monthly_col_product')}</th><th>${t('monthly_col_weight')}</th>
        <th>${t('monthly_col_shelf')} (${t('carton_unit_word')})</th><th>${t('monthly_col_shelf')} ${t('monthly_col_expiry')}</th>
        <th>${t('monthly_col_back')} (${t('carton_unit_word')})</th><th>${t('monthly_col_back')} ${t('monthly_col_expiry')}</th>
        <th>${t('field_notes')}</th><th>${t('field_reason')}</th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table>
  `;
  toast(t('print_hint'));
  setTimeout(()=> window.print(), 300);
}

function attachAdminTabEvents(tab){
  if(tab==="branches") attachBranchesTabEvents();
  if(tab==="products") attachProductsTabEvents();
  if(tab==="sos") attachSosTabEvents();
  if(tab==="users") attachUsersTabEvents();
  if(tab==="appearance") attachAppearanceTabEvents();
}

