/* ---------------- MODAL SCROLL LOCK ----------------
   Prevents the background page from scrolling while any .overlay modal
   is open, and ensures the modal itself becomes the scroll container so
   its close button is always reachable even on small screens. */
(function(){
  const lockBody = ()=>{
    const hasOverlay = !!document.querySelector('.overlay');
    document.body.style.overflow = hasOverlay ? 'hidden' : '';
  };
  const observer = new MutationObserver(lockBody);
  document.addEventListener('DOMContentLoaded', ()=>{
    observer.observe(document.body, { childList: true });
    lockBody();
  });
})();

loadAll();
